/**
 * The commands from one call, and when to call `tick` next.
 */
public struct TransferState {
    public var commands: [TransferCommand]
    public var nextDeadline: UInt64?
    public var late: Bool
    public var finished: Bool
    /**
     * Bytes of the object verified so far, each piece counted once.
     */
    public var verifiedBytes: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(commands: [TransferCommand], nextDeadline: UInt64?, late: Bool, finished: Bool, 
        /**
         * Bytes of the object verified so far, each piece counted once.
         */verifiedBytes: UInt64) {
        self.commands = commands
        self.nextDeadline = nextDeadline
        self.late = late
        self.finished = finished
        self.verifiedBytes = verifiedBytes
    }
}

#if compiler(>=6)
extension TransferState: Sendable {}
#endif


extension TransferState: Equatable, Hashable {
    public static func ==(lhs: TransferState, rhs: TransferState) -> Bool {
        if lhs.commands != rhs.commands {
            return false
        }
        if lhs.nextDeadline != rhs.nextDeadline {
            return false
        }
        if lhs.late != rhs.late {
            return false
        }
        if lhs.finished != rhs.finished {
            return false
        }
        if lhs.verifiedBytes != rhs.verifiedBytes {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(commands)
        hasher.combine(nextDeadline)
        hasher.combine(late)
        hasher.combine(finished)
        hasher.combine(verifiedBytes)
    }
}



