// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What the shell must do or learn, in order.
 */

public enum PeerLinkEvent {
    
    /**
     * Send this text frame on the channel.
     */
    case sendText(text: String
    )
    /**
     * Send this binary frame on the channel.
     */
    case sendBinary(bytes: Data
    )
    /**
     * The link closed; close the channel and connection.
     */
    case closed(reason: String
    )
    case report(report: RequestReport
    )
    /**
     * The request's bytes, or `None`. Resolved once, possibly before the
     * link finishes draining the response. The shell hashes them.
     */
    case resolved(id: UInt64?, bytes: Data?
    )
    case haveChanged(keys: [String]
    )
    case scheduleChanged
    /**
     * The remote wants this key; answer with `serve_response`.
     */
    case serveRequest(key: String
    )
    /**
     * The remote wants these pieces of this key. Answer with the whole held
     * object; the link sends only the span. Charge the span's bytes against
     * upload allowances.
     */
    case serveRange(key: String, span: PieceSpan
    )
    case uploadCancelled(bytes: UInt64
    )
    case progress(received: UInt64, size: UInt64
    )
}


#if compiler(>=6)
extension PeerLinkEvent: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePeerLinkEvent: FfiConverterRustBuffer {
    typealias SwiftType = PeerLinkEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PeerLinkEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .sendText(text: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .sendBinary(bytes: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .closed(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .report(report: try FfiConverterTypeRequestReport.read(from: &buf)
        )
        
        case 5: return .resolved(id: try FfiConverterOptionUInt64.read(from: &buf), bytes: try FfiConverterOptionData.read(from: &buf)
        )
        
        case 6: return .haveChanged(keys: try FfiConverterSequenceString.read(from: &buf)
        )
        
        case 7: return .scheduleChanged
        
        case 8: return .serveRequest(key: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .serveRange(key: try FfiConverterString.read(from: &buf), span: try FfiConverterTypePieceSpan.read(from: &buf)
        )
        
        case 10: return .uploadCancelled(bytes: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 11: return .progress(received: try FfiConverterUInt64.read(from: &buf), size: try FfiConverterUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PeerLinkEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .sendText(text):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(text, into: &buf)
            
        
        case let .sendBinary(bytes):
            writeInt(&buf, Int32(2))
            FfiConverterData.write(bytes, into: &buf)
            
        
        case let .closed(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .report(report):
            writeInt(&buf, Int32(4))
            FfiConverterTypeRequestReport.write(report, into: &buf)
            
        
        case let .resolved(id,bytes):
            writeInt(&buf, Int32(5))
            FfiConverterOptionUInt64.write(id, into: &buf)
            FfiConverterOptionData.write(bytes, into: &buf)
            
        
        case let .haveChanged(keys):
            writeInt(&buf, Int32(6))
            FfiConverterSequenceString.write(keys, into: &buf)
            
        
        case .scheduleChanged:
            writeInt(&buf, Int32(7))
        
        
        case let .serveRequest(key):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(key, into: &buf)
            
        
        case let .serveRange(key,span):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(key, into: &buf)
            FfiConverterTypePieceSpan.write(span, into: &buf)
            
        
        case let .uploadCancelled(bytes):
            writeInt(&buf, Int32(10))
            FfiConverterUInt64.write(bytes, into: &buf)
            
        
        case let .progress(received,size):
            writeInt(&buf, Int32(11))
            FfiConverterUInt64.write(received, into: &buf)
            FfiConverterUInt64.write(size, into: &buf)
            
        }
    }
}


