// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * What the shell must do, in order.
 */

public enum TransferCommand {
    
    /**
     * Send a framing 2 `want` for these pieces on this peer's link.
     */
    case request(peer: UInt64, span: PieceSpan
    )
    /**
     * Fetch these pieces from origin with an HTTP `Range` request.
     */
    case fetchOrigin(span: PieceSpan
    )
    /**
     * Abort the peer's request for this object.
     */
    case cancel(peer: UInt64
    )
    /**
     * As `Cancel`, for a hopeless request; the shell may count it abandoned.
     */
    case abandon(peer: UInt64
    )
    /**
     * A piece failed its hash: ban the peer for this object.
     */
    case ban(peer: UInt64
    )
    /**
     * The whole object, every piece and the whole digest verified. The shell
     * aborts any origin fetch still running.
     */
    case deliver(bytes: Data
    )
    /**
     * Fetch the object whole from origin; abort any origin range fetch.
     */
    case fail
}


#if compiler(>=6)
extension TransferCommand: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeTransferCommand: FfiConverterRustBuffer {
    typealias SwiftType = TransferCommand

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> TransferCommand {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .request(peer: try FfiConverterUInt64.read(from: &buf), span: try FfiConverterTypePieceSpan.read(from: &buf)
        )
        
        case 2: return .fetchOrigin(span: try FfiConverterTypePieceSpan.read(from: &buf)
        )
        
        case 3: return .cancel(peer: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .abandon(peer: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 5: return .ban(peer: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .deliver(bytes: try FfiConverterData.read(from: &buf)
